'use strict';
const D=window.CAREER_DATA, KEY='analystpath.workspace.v1';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',folder:'M3 7h7l2-3h7a2 2 0 0 1 2 2v13H3z',briefcase:'M8 7V4h8v3 M3 8h18v12H3z M3 12l9 3 9-3 M12 12v4',chart:'M4 20V10h4v10 M10 20V4h4v16 M16 20v-8h4v8',arrow:'M5 12h14 M14 7l5 5-5 5',external:'M14 3h7v7 M21 3l-11 11 M10 3H3v18h18v-7',check:'M5 12l4 4L19 6',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',plus:'M12 5v14 M5 12h14',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',target:'M21 12a9 9 0 1 1-9-9 M12 7a5 5 0 1 0 5 5 M12 12l9-9 M16 3h5v5',award:'M8 14l-1 7 5-3 5 3-1-7 M12 15a6 6 0 1 0 0-12 6 6 0 0 0 0 12',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',database:'M3 6c0-5 18-5 18 0s-18 5-18 0 M3 6v12c0 5 18 5 18 0V6 M3 12c0 5 18 5 18 0',sheet:'M4 3h16v18H4z M4 8h16 M4 13h16 M4 18h16 M10 8v13 M15 8v13',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0 M12 8v4 M10 10h4',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21c0-8 16-8 16 0',close:'M6 6l12 12 M18 6L6 18',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',edit:'M14 5l5 5 M3 21l2-7L17 2l5 5L10 19z',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.1 M3 12h.1 M3 18h.1',layers:'M12 3l10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.file}"/></svg>`;
const id=()=>crypto.randomUUID?.()||Math.random().toString(36).slice(2);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const fmt=(s,opts={day:'numeric',month:'short'})=>s?new Date(s+'T12:00:00').toLocaleDateString('en-IN',opts):'—';
function weekStart(){let d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
const defaults=()=>({version:1,profile:{name:'',degree:'BA',role:'Operations Supervisor',relocation:'Open to relocation',weeklyHours:5,target:'analyst'},tasks:{},projects:{},customProjects:[],week:{},logs:[],leads:[],applications:[],certificates:[],skills:{excel:'Used at work',sql:'Learning',powerbi:'Learning'}});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||defaults()}catch{state=defaults()}
state={...defaults(),...state,profile:{...defaults().profile,...state.profile},skills:{...defaults().skills,...state.skills}};
let route='dashboard',learnTab='excel',resourceFilter='All',oppFilter='All',appView='table',appFilter='All',query='';
let toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Storage is full or unavailable. Export a backup now.');return false}}
const pct=(n,d)=>d?Math.round(n/d*100):0;
const doneFor=t=>t.tasks.filter(x=>state.tasks[x.id]).length;
const totalDone=()=>D.learning.reduce((a,t)=>a+doneFor(t),0);
const allTasks=()=>D.learning.flatMap(t=>t.tasks);
const projectList=()=>[...D.projects,...state.customProjects];
const projectState=p=>state.projects[p.id]||{status:'Not started',checks:{},url:'',next:''};
const badge=(s,cls='')=>`<span class="badge ${cls}">${esc(s)}</span>`;
const btn=(label,action,ico='',cls='',attrs='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const ext=(url,label)=>`<a class="external-link" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('external')}</a>`;
function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
const skillIcon=t=>icon(t==='excel'?'sheet':t==='sql'?'database':'chart');
const appStages=['Saved','Applied','Assessment','Interview','Offer','Closed'];
const checkFields=[['official','Original employer / official notice checked'],['eligible','Essential qualifications and experience checked'],['terms','Location, contract and internship terms checked'],['noagent','No agent payment or paid experience certificate']];
const verified=l=>checkFields.every(([k])=>l[k])&&l.fee==='0'&&l.eligibility==='Eligible';
function heading(title,sub,actions='',eyebrow='YOUR CAREER WORKSPACE'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`}
function empty(title,desc,action,label,ico='folder'){return `<div class="card page-empty"><div class="empty-icon">${icon(ico)}</div><h3>${title}</h3><p>${desc}</p>${action?btn(label,action,'plus','primary'):''}</div>`}
function section(title,sub,action=''){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${action}</div>`}
function renderNav(){const nav=[['dashboard','grid','Overview'],['learning','book','Learning path'],['resources','award','Free resources'],['datasets','database','Free data sources'],['projects','folder','My projects'],['opportunities','search','Find opportunities'],['applications','briefcase','Applications'],['evidence','chart','Progress & evidence'],['roles','layers','Compare roles'],['templates','file','Templates']];$('#navigation').innerHTML=nav.map(([key,ico,title],i)=>`${key==='roles'?'<div class="nav-divider"></div>':''}<a class="nav-link ${route===key?'active':''}" href="#${key}" ${route===key?'aria-current="page"':''}>${icon(ico)}${title}${key==='applications'&&state.applications.length?`<span class="nav-counter">${state.applications.length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=nav.find(n=>n[0]===route)?.[2]||'Search';$('#search-icon').innerHTML=icon('search')}
function render(){renderNav();const f={dashboard:dashboard,learning:learning,resources:resources,datasets:dataSources,projects:projects,opportunities:opportunities,applications:applications,evidence:evidence,roles:roles,templates:templates,search:searchPage};$('#main').innerHTML=(f[route]||dashboard)()}
function go(r){if(location.hash.slice(1)===r){route=r;render()}else location.hash=r;$('#sidebar').classList.remove('open')}
function dashboard(){const weekLogs=state.logs.filter(l=>l.date>=weekStart()&&l.date<=today()),mins=weekLogs.reduce((s,l)=>s+(+l.minutes||0),0),goal=state.profile.weeklyHours*60,started=projectList().filter(p=>projectState(p).status!=='Not started').length,active=state.applications.filter(a=>!['Closed','Offer'].includes(a.status)).length;
const focus=[['practice','Practise one SQL concept','Write and check five SELECT queries.'],['build','Start your operations project','Set up a small, clearly synthetic dataset.'],['review','Review one genuine opportunity','Check eligibility in the original notice.']];
return heading(`${state.profile.name?'Keep going, '+esc(state.profile.name.split(' ')[0])+'.':'Your next chapter starts here.'}`,'A practical path from operations to data analytics.',`<span class="date">${icon('calendar')}${fmt(today(),{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</span>${btn('Log progress','log','plus','primary')}`,'MAKE PROGRESS, AT YOUR PACE')+
`<div class="hero"><div><div class="eyebrow"><span></span> YOUR EXPERIENCE IS YOUR STARTING POINT</div><h2>From managing operations<br>to understanding the data.</h2><p>Build on your Excel experience. Learn SQL and Power BI.<br>Turn each small step into evidence you can show.</p>${btn('Continue learning','continue','arrow','lime')}</div><div class="hero-art"><div class="roadmap"><div class="roadmap-step"><div class="step-icon">${icon('book')}</div><strong>Learn the skills</strong><small>Excel · SQL · Power BI</small></div><div class="roadmap-step"><div class="step-icon">${icon('folder')}</div><strong>Build the proof</strong><small>Projects & evidence</small></div><div class="roadmap-step"><div class="step-icon">${icon('briefcase')}</div><strong>Find your next role</strong><small>Genuine opportunities</small></div><div class="hero-caption">YOUR PATH, ONE PRACTICAL STEP AT A TIME</div></div></div></div>
<div class="stat-grid">${[[`${totalDone()}<span>/ 18</span>`,'Learning steps completed','book','Progress you have recorded'],[String(started),'Projects in motion','folder',`${projectList().filter(p=>projectState(p).status==='Complete').length} marked complete`],[String(active),'Active applications','briefcase',`${state.applications.filter(a=>a.status==='Interview').length} at interview stage`],[`${(mins/60).toFixed(mins%60?1:0)}<span>/ ${esc(state.profile.weeklyHours)} hrs</span>`,'Learning this week','clock','Your suggested weekly time goal']].map(([n,t,i,f])=>`<div class="stat"><div class="stat-top">${t}${icon(i)}</div><div class="stat-number">${n}</div><div class="stat-foot">${f}</div></div>`).join('')}</div>
<div class="card data-dashboard-link"><div><strong>Find data for your next project</strong><p>Browse free dataset sources for operations, India, business, health, sports and more.</p></div><a class="button soft" href="#datasets">Explore free data ${icon('database')}</a></div>
<div class="dashboard-grid"><div><div class="section-block">${section('Your learning path','Build confidence through practice.',`<a class="button ghost" href="#learning">View learning plan ${icon('arrow')}</a>`)}<div class="learning-cards">${D.learning.map(t=>`<a href="#learning" data-learning="${t.id}" class="card skill-card"><div class="skill-icon ${t.id}">${skillIcon(t.id)}</div>${badge(t.id==='excel'?'Daily experience':'Learning',t.id==='excel'?'green':'amber')}<h3>${t.name}</h3><p>${esc(t.tagline)}</p><div class="progress-line"><span style="width:${pct(doneFor(t),6)}%"></span></div><div class="skill-progress-label"><span>${doneFor(t)} of 6 steps</span><span>${pct(doneFor(t),6)}%</span></div><div class="card-bottom"><span>${doneFor(t)?'Continue practising':'Open your plan'}</span>${icon('arrow')}</div></a>`).join('')}</div></div>
<div class="section-block">${section('Build something you can show','Practical projects, grounded in your experience.',`<a href="#projects" class="button ghost">All projects ${icon('arrow')}</a>`)}${projectList().slice(0,2).map(p=>`<a href="#projects" class="card project-preview"><div class="project-icon">${icon('chart')}</div><div><h3>${esc(p.title)}</h3><p>${esc(p.tools.join(' · '))} &nbsp; / &nbsp; ${esc(p.estimated)}</p></div>${badge(projectState(p).status,projectState(p).status==='Not started'?'gray':'green')}</a>`).join('')}</div>
<div class="section-block">${section('Your next application','Keep your next move within reach.')}<div class="card empty-inline">${icon('briefcase')}<span>${state.applications.length?`${state.applications.length} application${state.applications.length===1?'':'s'} recorded. Check your next actions.`:'Your application story is ready to begin.'}</span><a class="button soft" href="#applications">Open tracker ${icon('arrow')}</a></div></div></div>
<div class="dashboard-right"><div class="section-block"><div class="card focus-card"><div class="row-between"><div class="eyebrow">A LITTLE FOCUS GOES A LONG WAY</div>${badge('This week','gray')}</div><h3>Three small steps forward</h3>${focus.map(([k,t,d])=>`<label class="check-row"><input type="checkbox" data-week="${k}" ${state.week[weekStart()+k]?'checked':''}><span><span class="check-title">${t}</span><span class="check-desc">${d}</span></span></label>`).join('')}<div class="weekly-goal"><span>Weekly learning time</span><strong>${mins} / ${goal} min</strong></div><div class="progress-line"><span style="width:${Math.min(100,pct(mins,goal))}%"></span></div><button class="button ghost small" style="margin-top:10px;font-size:9px" data-action="profile">Adjust your weekly goal ${icon('arrow')}</button></div><div class="note-box"><strong>${icon('spark')}Real experience. Real confidence.</strong><p>Your Operations Supervisor work already has value. Add skills and project proof without changing your story.</p><a class="button ghost" href="#roles" style="font-size:9px;margin-top:8px">Explore your role options ${icon('arrow')}</a></div></div></div></div><div class="profile-chips"><span>${icon('user')}${esc(state.profile.degree)} graduate</span><span>${icon('briefcase')}${esc(state.profile.role)}</span><span>${icon('pin')}${esc(state.profile.relocation)}</span><span>${icon('award')}Free resources only</span></div>`}
function learning(){const t=D.learning.find(x=>x.id===learnTab)||D.learning[0],p=pct(doneFor(t),6),res=D.resources.filter(r=>r.skill===t.name);return heading('Build skills you can use.','A guided sequence. Practise, check your work, then save the evidence.',btn('Log a practice session','log','plus','primary'),'LEARNING PATH')+`<div class="toolbar"><div class="tabs">${D.learning.map(t=>`<button class="tab ${learnTab===t.id?'active':''}" data-action="learn-tab" data-id="${t.id}">${t.name} <span class="muted">${doneFor(t)}/6</span></button>`).join('')}</div><span class="small muted">Check a step when you can repeat it yourself.</span></div><div class="two-col"><div class="card panel"><div class="panel-head"><div><h2>${t.name} practice plan</h2><p>${esc(t.tagline)}</p></div><div class="progress-ring" style="--p:${p}"><span>${p}%</span></div></div><div class="progress-line"><span style="width:${p}%"></span></div><div class="task-list">${t.tasks.map((a,i)=>`<label class="check-row"><input type="checkbox" data-task="${a.id}" ${state.tasks[a.id]?'checked':''}><span><span class="check-title">${i+1}. ${esc(a.title)}</span><span class="check-desc">${esc(a.detail)}</span></span><span class="task-time">~${a.minutes} min</span></label>`).join('')}</div><p class="inline-note">These are learning steps, not claimed qualifications. Save a query, workbook or screenshot to show what you can do.</p></div><div>${section('Your skill confidence','Update this after independent practice.')}<div class="card panel" style="margin-bottom:22px"><label class="field">${t.name} · self assessment<select data-confidence="${t.id}">${['Learning','Can do with guidance','Independent practice','Used at work'].map(x=>`<option ${state.skills[t.id]===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="inline-note">Your current Excel use is a starting point. Record the specific tasks you actually perform.</p></div>${section('Learn for free','Official learning and hands-on practice.')}<div class="resource-list">${res.map(resourceItem).join('')}</div><a href="#resources" class="button ghost" style="margin-top:12px">See all free resources ${icon('arrow')}</a></div></div>`}
function resourceItem(r){return `<article class="resource-item"><div class="row-between"><span class="eyebrow">${esc(r.provider)}</span>${badge(r.type,r.type==='Certificate'||r.type==='Digital badge'?'green':'gray')}</div><h3 style="margin-top:12px">${esc(r.title)}</h3><p>${esc(r.description)}</p><p><strong>${esc(r.credential)}</strong><br>${esc(r.note)}</p>${ext(r.url,'Open free resource')}</article>`}
function resources(){const filtered=D.resources.filter(r=>resourceFilter==='All'||(resourceFilter==='Free credentials'?['Certificate','Digital badge'].includes(r.type):r.skill===resourceFilter));return heading('Good learning. Zero course fees.','A small, curated library with clear distinctions between learning and credentials.',btn('Add a certificate','certificate','plus','primary'),'FREE RESOURCE LIBRARY')+`<div class="callout">${icon('info')}<div>Course certificates and digital badges show learning. <strong>Microsoft Learn training is free; the PL-300 certification exam is separate and normally paid.</strong> Power BI Desktop is free on supported Windows devices; paid sharing or capacity is not required for your portfolio.</div></div><div class="toolbar"><div class="tabs">${['All','Free credentials','Excel','SQL','Power BI'].map(x=>`<button class="tab ${resourceFilter===x?'active':''}" data-action="resource-filter" data-id="${x}">${x}</button>`).join('')}</div><span class="small muted">Links reviewed 17 Nov 2026 · check current provider terms</span></div><div class="resource-grid">${filtered.map(resourceItem).join('')}</div><div class="spacer"></div>${section('Your certificate shelf','Only credentials you add appear here.')}${state.certificates.length?`<div class="table-wrap"><table><thead><tr><th>Credential</th><th>Provider</th><th>Earned</th><th>Evidence</th><th></th></tr></thead><tbody>${state.certificates.map(c=>`<tr><td><strong>${esc(c.title)}</strong>${badge(c.type||'Course completion','gray')}</td><td>${esc(c.provider)}</td><td>${fmt(c.date)}</td><td>${c.url?ext(c.url,'View evidence'):'No link yet'}</td><td>${btn('Edit','certificate','edit','ghost',`data-id="${c.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('A place for your earned credentials','Finish a free course or badge, then save the title, date and proof here.','certificate','Add earned credential','award')}`}
function projects(){return heading('Make your skills visible.','Practical project briefs. Use public or clearly labelled synthetic data.',btn('Add a project','project-brief','plus','primary'),'YOUR PROJECT WORKBENCH')+`<div class="callout">${icon('info')}<div>These are <strong>suggested independent learning projects</strong>. Keep them under Projects on your CV. Use employer data only with permission and protect confidential information.</div></div><div class="cards-grid">${projectList().map((p,i)=>{const s=projectState(p),n=p.deliverables.filter((x,k)=>s.checks[k]).length;return `<article class="card project-card"><div class="row-between"><div class="skill-icon ${i===1?'sql':i===2?'powerbi':''}" style="margin:0">${icon(i===1?'database':'chart')}</div>${badge(s.status,s.status==='Complete'?'green':s.status==='Not started'?'gray':'amber')}</div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="project-meta">${p.tools.map(t=>badge(t,'gray')).join('')}</div><div class="progress-line"><span style="width:${pct(n,p.deliverables.length)}%"></span></div><div class="checklist-summary">${n} / ${p.deliverables.length} deliverables · ${esc(p.estimated)}</div>${s.next?`<p class="inline-note"><strong>Next:</strong> ${esc(s.next)}</p>`:''}${btn(s.status==='Not started'?'Open project brief':'Continue project','project','arrow','',`data-id="${p.id}"`)}</article>`}).join('')}</div><div class="note-box"><strong>${icon('spark')}The evidence matters more than the title.</strong><p>A checked workbook, readable SQL queries and a clear explanation of your findings tell a stronger story than an unsupported skill claim. Use the project README template to document your work.</p><a href="#templates" class="button ghost">Open reusable templates ${icon('arrow')}</a></div>`}
function opportunities(){const list=state.leads.filter(l=>oppFilter==='All'||(oppFilter==='₹0 only'?l.fee==='0':oppFilter==='Needs checks'?!verified(l):l.role===oppFilter));return heading('Find a genuine next step.','Start with the original source. Check fit and terms before applying.',btn('Save an opportunity','lead','plus','primary'),'OPPORTUNITY RESEARCH')+`<div class="callout">${icon('info')}<div><strong>Official sources, not live vacancy recommendations.</strong> Check the current notice, deadline, eligibility and employer. Registration on a portal does not verify every listing. Never pay an agent for a job or an experience certificate.</div></div>${section('Places to look','Free browsing. Verify any application or exam fee in the original notice.')}<div class="source-grid">${D.opportunitySources.map((s,i)=>`<article class="card source-card"><div class="eyebrow">SOURCE 0${i+1}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><details><summary class="small muted" style="font-size:9px;cursor:pointer">What to check</summary><p>${esc(s.note)}</p><p>Search: ${esc(s.terms)}</p></details><div style="margin-top:10px">${ext(s.url,'Visit official portal')}</div></article>`).join('')}</div>${section('Your saved opportunities','Keep an advert, a decision and the next action together.')}<div class="toolbar"><div class="filters"><select id="opportunity-filter" aria-label="Filter opportunities">${['All','₹0 only','Needs checks',...D.roleTracks.map(r=>r.title)].map(x=>`<option ${oppFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><span class="small muted">${list.length} saved ${list.length===1?'lead':'leads'}</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Role & employer</th><th>Fit decision</th><th>Deadline</th><th>Fee</th><th>Checks</th><th>Next step</th></tr></thead><tbody>${list.map(l=>`<tr><td><button class="text-button" data-action="lead" data-id="${l.id}"><strong>${esc(l.title)}</strong></button><small>${esc(l.organisation)}</small>${ext(l.url,'Original source')}</td><td>${badge(l.eligibility,l.eligibility==='Eligible'?'green':l.eligibility==='Not eligible'?'red':'amber')}<small>${esc(l.location||'Location not recorded')}</small></td><td class="${l.deadline&&l.deadline<today()?'followup-due':''}">${fmt(l.deadline)}${l.deadline&&l.deadline<today()?'<small>Past deadline</small>':''}</td><td>${l.fee==='0'?'₹0':l.fee==='Unknown'?'Unknown':esc(l.fee)}</td><td>${badge(verified(l)?'Ready to review':`${checkFields.filter(([k])=>l[k]).length}/4 checked`,verified(l)?'green':'gray')}<small>${l.checked?'Checked '+fmt(l.checked):'No check date'}</small></td><td>${state.applications.some(a=>a.leadId===l.id)?'<a href="#applications" class="text-button">In application tracker →</a>':btn('Track application','from-lead','arrow','ghost',`data-id="${l.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty(state.leads.length?'No opportunities match this view':'Your research starts here',state.leads.length?'Choose another filter or save a matching opportunity.':'Save a real advert from an employer or official portal. Add its reference, requirements and your eligibility checks.','lead','Save first opportunity','search')}`}
function applications(){let list=state.applications.filter(a=>appFilter==='All'||a.status===appFilter);return heading('Keep your next move organised.','Track genuine applications, follow-ups and the evidence you send.',btn('Add application','application','plus','primary'),'APPLICATION TRACKER')+`<div class="toolbar"><div class="tabs">${['table','board'].map(x=>`<button class="tab ${appView===x?'active':''}" data-action="app-view" data-id="${x}">${icon(x==='table'?'list':'grid')} ${x==='table'?'List view':'Board view'}</button>`).join('')}</div><div class="filters"><select id="application-filter" aria-label="Filter application status">${['All',...appStages].map(x=>`<option ${appFilter===x?'selected':''}>${x}</option>`).join('')}</select>${btn('Export CSV','csv','download')}</div></div>${state.applications.length?appView==='board'?`<div class="kanban">${[['Saved'],['Applied'],['Assessment','Interview'],['Offer','Closed']].map(stages=>{const entries=list.filter(a=>stages.includes(a.status));return `<section class="kanban-col"><div class="kanban-head">${stages.join(' / ')}<span>${entries.length}</span></div>${entries.map(a=>`<div class="card application-card"><div class="row-between">${badge(a.status,a.status==='Offer'?'green':'gray')}<button class="icon-button" aria-label="Edit ${esc(a.title)}" data-action="application" data-id="${a.id}">${icon('edit')}</button></div><h3 style="margin-top:12px">${esc(a.title)}</h3><p>${esc(a.organisation)}</p><small>${esc(a.location||'Location to confirm')}</small>${a.followup?`<small class="${a.followup<=today()?'followup-due':''}">Follow up ${fmt(a.followup)}</small>`:''}<select class="status-select" aria-label="Status of ${esc(a.title)}" data-application-status="${a.id}">${appStages.map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')}</section>`}).join('')}</div>`:list.length?`<div class="table-wrap"><table><thead><tr><th>Role & employer</th><th>Status</th><th>Applied</th><th>Follow up</th><th>Next action</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><strong>${esc(a.title)}</strong><small>${esc(a.organisation)} · ${esc(a.location||'Location to confirm')}</small></td><td><select class="status-select" aria-label="Status of ${esc(a.title)}" data-application-status="${a.id}">${appStages.map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${fmt(a.applied)}</td><td class="${a.followup&&a.followup<=today()&&!['Offer','Closed'].includes(a.status)?'followup-due':''}">${fmt(a.followup)}</td><td style="white-space:normal;max-width:250px">${esc(a.next||'Add a next action')}</td><td>${btn('Edit','application','edit','ghost',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No applications in this stage','Choose another status to see your records.','','','briefcase'):empty('A clear view of your next chapter','Add an application when you have a real role to track. Your stages, follow-up dates and notes stay together.','application','Add first application','briefcase')}<div class="note-box"><strong>${icon('file')}Keep every application honest.</strong><p>Use your real Operations Supervisor title, BA qualification and actual responsibilities. Put SQL and Power BI learning under Skills or Projects. Record the CV version and evidence you shared so you can prepare confidently.</p><a class="button ghost" href="#templates">Use an application template ${icon('arrow')}</a></div>`}
function evidence(){const mins=state.logs.reduce((s,l)=>s+(+l.minutes||0),0),days=Array.from({length:7},(_,i)=>{const d=new Date(weekStart()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);const key=d.toISOString().slice(0,10);return{key,label:d.toLocaleDateString('en',{weekday:'narrow',timeZone:'UTC'}),mins:state.logs.filter(l=>l.date===key).reduce((s,l)=>s+(+l.minutes||0),0)}}),max=Math.max(...days.map(d=>d.mins),30);return heading('Give your progress a paper trail.','Record what you practised, what you can show and what comes next.',btn('Log progress','log','plus','primary'),'PROGRESS & EVIDENCE')+`<div class="two-col"><div><div class="stat-grid" style="grid-template-columns:repeat(3,1fr)">${[[state.logs.length,'Practice entries'],[(mins/60).toFixed(1),'Hours recorded'],[state.logs.filter(l=>l.url).length,'Evidence links']].map(([n,t])=>`<div class="stat"><div class="stat-top">${t}</div><div class="stat-number">${n}</div></div>`).join('')}</div>${state.logs.length?`<div class="timeline">${[...state.logs].sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created)).map(l=>`<article class="log-entry"><div class="log-date"><strong>${fmt(l.date,{day:'numeric',month:'short'})}</strong>${fmt(l.date,{year:'numeric'})}</div><div class="log-content">${badge(l.area,'gray')} ${badge(l.minutes+' min','gray')}<h3>${esc(l.title)}</h3><p>${esc(l.notes)}</p>${l.next?`<p><strong>Next:</strong> ${esc(l.next)}</p>`:''}${l.url?ext(l.url,'Open evidence'):''}</div><div class="log-actions"><button class="icon-button" data-action="log" data-id="${l.id}" aria-label="Edit progress entry">${icon('edit')}</button></div></article>`).join('')}</div>`:empty('Your first entry is a small win','Write down one thing you practised. A short note, a saved query or a workbook is enough to begin.','log','Record your first step','chart')}</div><div><div class="card panel"><div class="panel-head"><div><h2>This week’s rhythm</h2><p>Minutes logged · week of ${fmt(weekStart())}</p></div>${icon('chart')}</div><div class="mini-chart">${days.map(d=>`<div class="chart-column"><span class="minutes">${d.mins||''}</span><div class="chart-bar" style="height:${Math.max(3,d.mins/max*60)}px" title="${d.key}: ${d.mins} minutes"></div><small>${d.label}</small></div>`).join('')}</div><p class="inline-note">Progress comes from your saved entries. Nothing is assumed or filled in for you.</p></div><div class="note-box"><strong>What counts as evidence?</strong><p>A workbook with checked totals. A query with an explanation. Dashboard screenshots. An earned certificate link. A real work example you are allowed to share.</p><p>Describe what the evidence demonstrates and keep confidential employer data private.</p></div></div></div>`}
function roles(){return heading('More than one way forward.','Compare the work, build the gaps and check each actual advertisement.','','ROLE EXPLORER')+`<div class="callout">${icon('info')}<div><strong>Your base: BA + Operations Supervisor experience + daily Excel use.</strong> SQL and Power BI are still in progress. These are qualitative guides, not eligibility decisions or guaranteed job matches.</div></div><div class="role-grid">${D.roleTracks.map(r=>`<article class="card role-card">${state.profile.target===r.id?`<span class="role-target" title="Your current focus">${icon('target')}</span>`:''}${badge(r.fit,r.id==='govt-contract'?'green':'gray')}<h3>${esc(r.title)}</h3><h4>Your relevant foundation</h4><p>${esc(r.strengths)}</p><h4>Skills or evidence to build</h4><p>${esc(r.gaps)}</p><h4>Check before applying</h4><p>${esc(r.checks)}</p><h4>A practical next step</h4><p>${esc(r.next)}</p>${btn(state.profile.target===r.id?'Current focus':'Set as my focus','target','target',state.profile.target===r.id?'soft':'',`data-id="${r.id}"`)}</article>`).join('')}</div><div class="role-compare">${section('A few useful distinctions','Let the actual advert decide your eligibility.')}<div class="table-wrap"><table><thead><tr><th></th><th>Data Analyst</th><th>Govt MIS / DEO</th><th>Project / Programme Assistant</th><th>Contract Operations / MIS</th></tr></thead><tbody><tr><td><strong>Typical proof</strong></td><td>SQL, analysis and dashboard projects</td><td>Typing, computer proficiency, accurate records</td><td>Coordination, documentation, reporting</td><td>Actual operations and MIS responsibilities</td></tr><tr><td><strong>BA fit</strong></td><td>Employer-specific degree rules</td><td>Post-specific education and computer credentials</td><td>May require a named discipline or project experience</td><td>Advert-specific degree and essential experience</td></tr><tr><td><strong>Relocation check</strong></td><td>Work location and office policy</td><td>Posting, domicile and language requirements</td><td>Project location, travel and fieldwork</td><td>Payroll employer, tenure, pay and renewal</td></tr></tbody></table></div></div>`}
function templates(){return heading('Start with a useful structure.','Reusable prompts for honest applications, stronger evidence and weekly reviews.','','YOUR TEMPLATE TOOLKIT')+`<div class="cards-grid">${D.templates.map(t=>`<article class="card template-card">${badge(t.category,'gray')}<h3>${esc(t.title)}</h3><p>${esc(t.description)}</p>${btn('Open template','template','file','',`data-id="${t.id}"`)}</article>`).join('')}</div><div class="note-box"><strong>${icon('spark')}Make each template yours.</strong><p>Replace the brackets with facts you can explain. Leave out skills, results and experience you cannot support. A learning project is valuable without calling it employment.</p></div>`}
function searchPage(){const q=query.toLowerCase().trim(),items=[...D.learning.map(t=>({title:t.name+' learning plan',desc:t.tagline+' '+t.tasks.map(a=>a.title).join(' '),route:'learning',type:'Learning',learn:t.id})),...D.resources.map(r=>({title:r.title,desc:r.provider+' '+r.skill+' '+r.description,route:'resources',type:'Resource'})),...window.DATA_DIRECTORY.sources.map(s=>({title:s.name,desc:s.description+' '+s.category+' '+s.topics.join(' '),route:'datasets',type:'Data source',source:s.id})),...projectList().map(p=>({title:p.title,desc:p.description,route:'projects',type:'Project'})),...D.roleTracks.map(r=>({title:r.title,desc:r.gaps,route:'roles',type:'Role'})),...D.templates.map(t=>({title:t.title,desc:t.description,route:'templates',type:'Template'})),...state.applications.map(a=>({title:a.title,desc:a.organisation+' '+a.next,route:'applications',type:'Application'})),...state.leads.map(l=>({title:l.title,desc:l.organisation,route:'opportunities',type:'Opportunity'})),...state.logs.map(l=>({title:l.title,desc:l.notes,route:'evidence',type:'Evidence'}))].filter(i=>q&&(i.title+' '+i.desc).toLowerCase().includes(q));return heading('Find your next step.',q?`${items.length} result${items.length===1?'':'s'} for “${esc(query)}”`:'Type a topic, skill, role or employer in the search box.','','WORKSPACE SEARCH')+`<div class="search-results">${items.map(i=>`<a class="card search-result" href="#${i.route}" ${i.learn?`data-learning="${i.learn}"`:''} ${i.source?`data-source-link="${i.source}"`:''}>${badge(i.type,'gray')}<strong>${esc(i.title)} ${icon('arrow')}</strong><p>${esc(i.desc.slice(0,190))}</p></a>`).join('')||'<p class="muted small">Try “SQL”, “certificate”, “operations” or an employer you have saved.</p>'}</div>`}
function modal(title,subtitle,content){$('#modal-content').innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${content}`;if(!$('#modal').open)$('#modal').showModal()}
const options=(list,v)=>list.map(x=>`<option value="${esc(x)}" ${String(v)===String(x)?'selected':''}>${esc(x)}</option>`).join('');
function field(label,name,value='',type='text',full=false,extra=''){return `<label class="field ${full?'full':''}">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`}
function area(label,name,value='',full=true){return `<label class="field ${full?'full':''}">${label}<textarea name="${name}" maxlength="12000">${esc(value)}</textarea></label>`}
function select(label,name,list,value,full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}">${options(list,value)}</select></label>`}
function actions(existing=false,label='Save record'){return `<div class="modal-actions">${existing?btn('Delete','delete-record','trash','ghost danger left'):''}${btn('Cancel','close')}<button class="button primary" type="submit">${icon('check')}${label}</button></div>`}
let modalContext={};
function openLog(key){const l=state.logs.find(l=>l.id===key)||{date:today(),area:route==='learning'?D.learning.find(t=>t.id===learnTab).name:'Excel',minutes:30};modalContext={type:'log',id:key};modal(key?'Edit your progress entry':'One more step forward.','Record what you actually practised and the evidence it created.',`<form id="record-form"><div class="form-grid">${field('What did you work on?','title',l.title,'text',true,'required maxlength="180" placeholder="e.g. Practised LEFT JOIN with a tasks table"')}${field('Date','date',l.date,'date',false,`required max="${today()}"`)}${select('Skill or activity','area',['Excel','SQL','Power BI','Project','Application','Work evidence','Weekly review'],l.area)}${field('Minutes spent','minutes',l.minutes,'number',false,'required min="0" max="1440"')}${field('Evidence link (optional)','url',l.url,'url',false,'placeholder="https://…" maxlength="2000"')}${area('What did you learn or demonstrate?','notes',l.notes)}${area('Your next small step','next',l.next)}</div>${actions(!!key,'Save progress')}</form>`)}
function openProject(key){const p=projectList().find(p=>p.id===key);if(!p)return;const s=projectState(p);modalContext={type:'project',id:key};modal(esc(p.title),'Independent learning project · '+esc(p.estimated),`<p class="profile-summary">${esc(p.description)}</p><form id="record-form"><div class="form-grid">${select('Project stage','status',['Not started','Building','Ready for review','Complete'],s.status,true)}<div class="form-section"><h3>Deliverable checklist</h3><p>Check the pieces you have actually created and validated.</p>${p.deliverables.map((d,i)=>`<label class="check-row"><input type="checkbox" name="deliverable-${i}" ${s.checks[i]?'checked':''}><span class="check-title">${esc(d)}</span></label>`).join('')}</div>${field('Project / evidence link','url',s.url,'url',true,'placeholder="https://…" maxlength="2000"')}${area('Your next action','next',s.next)}</div><div style="margin-top:15px">${btn('Save & open README template','project-readme','file','ghost')}${state.customProjects.some(x=>x.id===key)?btn('Save & edit brief','edit-project-brief','edit','ghost',`data-id="${key}"`):''}</div>${actions(false,'Save project')}</form>`)}
function openProjectBrief(key,seed){const p=state.customProjects.find(p=>p.id===key)||seed||{deliverables:['Dataset and data dictionary','Validated analysis or dashboard','Findings and README'],tools:[]};modalContext={type:'project-brief',id:key};modal(key?'Edit your project brief':'Create your own project.','A small project with a clear question and checkable deliverables is enough.',`<form id="record-form"><div class="form-grid">${field('Project title','title',p.title,'text',true,'required maxlength="180"')}${area('Business question and project description','description',p.description)}${field('Tools · separate with commas','tools',p.tools.join(', '),'text',true,'required maxlength="360" placeholder="Excel, SQL, Power BI"')}${area('Deliverables · one per line','deliverables',p.deliverables.join('\n'))}${field('Time estimate','estimated',p.estimated,'text',true,'maxlength="100" placeholder="e.g. 4 focused sessions"')}</div><p class="inline-note">Label your data as public or synthetic. ${key?'Changing the deliverable list resets its checklist so you can check it against the new brief.':''}</p>${actions(!!key,'Save project brief')}</form>`)}
function openLead(key){const l=state.leads.find(l=>l.id===key)||{fee:'Unknown',eligibility:'Need clarification',role:D.roleTracks.find(r=>r.id===state.profile.target)?.title,checked:today()};modalContext={type:'lead',id:key};modal(key?'Review opportunity':'Save a real opportunity.','A portal link is a starting point. Record the original advertisement and check the details.',`<form id="record-form"><div class="form-grid">${field('Role title','title',l.title,'text',true,'required maxlength="180"')}${field('Employer / organisation','organisation',l.organisation,'text',false,'required maxlength="180"')}${field('Location / relocation','location',l.location,'text',false,'maxlength="180"')}${field('Original notice / employer URL','url',l.url,'url',true,'required placeholder="https://…" maxlength="2000"')}${select('Role track','role',D.roleTracks.map(r=>r.title),l.role,true)}${field('Advertisement reference','reference',l.reference,'text',false,'maxlength="180"')}${field('Deadline (if known)','deadline',l.deadline,'date')}${field('Last checked','checked',l.checked,'date',false,`max="${today()}"`)}${select('Application / exam fee','fee',['Unknown','0','Fee required'],l.fee)}${select('Eligibility decision','eligibility',['Need clarification','Eligible','Not eligible'],l.eligibility,true)}<div class="form-section"><h3>Verify before applying</h3><p>Confirm each point from the employer or original notice. Fee “0” means ₹0.</p>${checkFields.map(([k,t])=>`<label class="check-row"><input type="checkbox" name="${k}" ${l[k]?'checked':''}><span class="check-title">${t}</span></label>`).join('')}</div>${area('Eligibility details, internship terms and questions','notes',l.notes)}${area('Next action','next',l.next)}</div>${actions(!!key,'Save opportunity')}</form>`)}
function openApplication(key,lead){let a=state.applications.find(a=>a.id===key)||{status:'Saved',history:[]};if(lead)a={...a,title:lead.title,organisation:lead.organisation,location:lead.location,url:lead.url,deadline:lead.deadline,notes:lead.notes,next:lead.next,leadId:lead.id};modalContext={type:'application',id:key,leadId:a.leadId};modal(key?'Update application':'Track your next move.','Use “Saved” while considering a role. Add an applied date only after you submit.',`<form id="record-form"><div class="form-grid">${field('Role title','title',a.title,'text',true,'required maxlength="180"')}${field('Employer / organisation','organisation',a.organisation,'text',false,'required maxlength="180"')}${field('Location / relocation','location',a.location,'text',false,'maxlength="180"')}${field('Application / advert URL','url',a.url,'url',true,'placeholder="https://…" maxlength="2000"')}${select('Status','status',appStages,a.status)}${field('Applied on','applied',a.applied,'date',false,`max="${today()}"`)}${field('Follow-up date','followup',a.followup,'date')}${field('Application deadline','deadline',a.deadline,'date')}${field('CV version / evidence link','cv',a.cv,'text',true,'placeholder="e.g. Analyst CV v2, portfolio URL" maxlength="2000"')}${area('Next action','next',a.next)}${area('Notes · eligibility, contact, assessment or interview','notes',a.notes)}</div>${a.history?.length?`<details style="margin-top:15px"><summary class="small muted">Status history</summary>${a.history.map(h=>`<div class="history-line">${fmt(h.date)} · ${esc(h.status)}</div>`).join('')}</details>`:''}${actions(!!key,'Save application')}</form>`)}
function openCertificate(key){const c=state.certificates.find(c=>c.id===key)||{date:today(),type:'Course completion certificate'};modalContext={type:'certificate',id:key};modal('Keep proof of your learning.','Add a credential only after you earn it. Learning achievements are distinct from professional certification.',`<form id="record-form"><div class="form-grid">${field('Credential title','title',c.title,'text',true,'required maxlength="180"')}${field('Provider','provider',c.provider,'text',false,'required maxlength="180"')}${field('Earned on','date',c.date,'date',false,`required max="${today()}"`)}${select('Credential type','type',['Course completion certificate','Digital badge','Learning achievement'],c.type,true)}${field('Verification or saved evidence URL','url',c.url,'url',true,'placeholder="https://…" maxlength="2000"')}${area('Notes / what you practised','notes',c.notes)}</div>${actions(!!key,'Save credential')}</form>`)}
function openProfile(){modalContext={type:'profile'};modal('Your starting point.','Shape the plan around your real background and available time.',`<form id="record-form"><div class="form-grid">${field('First name (optional)','name',state.profile.name,'text',false,'maxlength="60"')}${field('Degree','degree',state.profile.degree,'text',false,'required maxlength="100"')}${field('Current role','role',state.profile.role,'text',true,'required maxlength="180"')}${field('Relocation preference','relocation',state.profile.relocation,'text',true,'maxlength="180"')}${field('Suggested learning hours / week','weeklyHours',state.profile.weeklyHours,'number',true,'required min="1" max="40" step="0.5"')}</div><p class="inline-note">5 hours is a suggested starting goal. Adjust it to fit your work schedule. Your focus role can be changed in Compare roles.</p>${actions(false,'Save preferences')}</form>`)}
function openTemplate(key){const t=D.templates.find(t=>t.id===key);if(!t)return;modalContext={type:'template',id:key};modal(esc(t.title),esc(t.description),`<div class="template-body">${esc(t.body)}</div><div class="modal-actions">${btn('Download .txt','download-template','download')}${btn('Copy template','copy-template','file','primary')}</div>`)}
function openBackup(){modalContext={type:'backup'};modal('Keep a copy of your progress.','Your records are saved in this browser on this device.',`<div class="callout">${icon('info')}<div>This workspace uses browser storage. It does not sync between devices. Clearing site data or using another browser starts a separate workspace. Export a backup regularly and restore it when you move.</div></div><div class="backup-buttons">${btn('Export full backup','export','download','primary')}${btn('Restore a backup','import','folder')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><p class="inline-note">The backup includes your preferences, learning checks, project progress, certificates, evidence and applications. Restore replaces the records in this browser. Export your current records first if you want to keep them.</p><div class="spacer"></div><h3>Take your applications with you</h3><p class="small muted">CSV is useful for Excel. Use the JSON backup to restore the whole workspace.</p>${btn('Export applications CSV','csv','download')}`)}
function download(name,data,type){const blob=new Blob([data],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csvExport(){const cols=['title','organisation','location','status','applied','followup','deadline','url','cv','next','notes'],cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download('analyst-path-applications-'+today()+'.csv','\uFEFF'+[cols,...state.applications.map(a=>cols.map(k=>a[k]))].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Applications CSV downloaded')}
function saveRecord(form){const f=Object.fromEntries(new FormData(form)),ctx=modalContext,now=new Date().toISOString();if(['url'].some(k=>f[k]&&safeUrl(f[k])==='#')){toast('Use a complete http or https URL.');return}if(ctx.type==='profile'){state.profile={...state.profile,...f,weeklyHours:+f.weeklyHours}}
else if(ctx.type==='project-brief'){const prior=state.customProjects.find(p=>p.id===ctx.id),record={id:prior?.id||id(),title:f.title,description:f.description,tools:f.tools.split(',').map(x=>x.trim()).filter(Boolean).slice(0,6),deliverables:f.deliverables.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20),estimated:f.estimated||'Your own pace'};if(!record.deliverables.length){toast('Add at least one deliverable.');return false}if(prior){state.customProjects=state.customProjects.map(p=>p.id===prior.id?record:p);if(JSON.stringify(prior.deliverables)!==JSON.stringify(record.deliverables))state.projects[prior.id]={...projectState(prior),checks:{}}}else state.customProjects.push(record)}
else if(ctx.type==='project'){const p=projectList().find(p=>p.id===ctx.id);state.projects[ctx.id]={status:f.status,url:f.url,next:f.next,checks:Object.fromEntries(p.deliverables.map((d,i)=>[i,form.elements['deliverable-'+i].checked]))}}
else{const listName={log:'logs',lead:'leads',application:'applications',certificate:'certificates'}[ctx.type];if(!listName)return;const prior=state[listName].find(x=>x.id===ctx.id),record={...prior,...f,id:prior?.id||id(),created:prior?.created||now,updated:now};if(ctx.type==='log')record.minutes=+f.minutes;if(ctx.type==='lead')checkFields.forEach(([k])=>record[k]=form.elements[k].checked);if(ctx.type==='application'){if(f.status!=='Saved'&&!f.applied&&['Applied','Assessment','Interview','Offer'].includes(f.status)){toast('Add the date you applied, or keep the status as Saved.');form.elements.applied.focus();return}record.leadId=ctx.leadId||'';record.history=prior?.history||[];if(!prior||prior.status!==record.status)record.history=[...record.history,{date:today(),status:record.status}]}
if(prior)state[listName]=state[listName].map(x=>x.id===prior.id?record:x);else state[listName].push(record)}
if(persist()){$('#modal').close();render();toast('Saved to your workspace');return true}return false}
function deleteRecord(){const listName={log:'logs',lead:'leads',application:'applications',certificate:'certificates','project-brief':'customProjects'}[modalContext.type];if(!listName)return;if(!confirm('Delete this record from this browser? This cannot be undone.'))return;state[listName]=state[listName].filter(x=>x.id!==modalContext.id);if(modalContext.type==='project-brief')delete state.projects[modalContext.id];if(persist()){$('#modal').close();render();toast('Record deleted')}}
function validateBackup(raw){if(!raw||raw.version!==1||!raw.profile||!Array.isArray(raw.logs)||!Array.isArray(raw.applications)||!Array.isArray(raw.leads))throw Error('This is not an Analyst Path version 1 backup.');const clean=defaults();const str=(v,max=12000)=>typeof v==='string'?v.slice(0,max):'';const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(new Date(v+'T12:00:00Z').getTime())?v:'';const url=v=>safeUrl(v)==='#'?'':str(v,2000);const validId=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(v)?v:id();['name','degree','role','relocation'].forEach(k=>clean.profile[k]=str(raw.profile[k],180)||clean.profile[k]);clean.profile.weeklyHours=Math.min(40,Math.max(1,+raw.profile.weeklyHours||5));if(D.roleTracks.some(r=>r.id===raw.profile.target))clean.profile.target=raw.profile.target;allTasks().forEach(t=>{if(raw.tasks?.[t.id]===true)clean.tasks[t.id]=true});Object.keys(raw.week||{}).slice(0,4000).forEach(k=>{if(/^\d{4}-\d{2}-\d{2}(practice|build|review)$/.test(k)&&raw.week[k]===true)clean.week[k]=true});D.learning.forEach(t=>{if(['Learning','Can do with guidance','Independent practice','Used at work'].includes(raw.skills?.[t.id]))clean.skills[t.id]=raw.skills[t.id]});clean.customProjects=(Array.isArray(raw.customProjects)?raw.customProjects:[]).slice(0,500).filter(p=>p&&typeof p==='object').map(p=>({id:validId(p.id),title:str(p.title,180),description:str(p.description),tools:(Array.isArray(p.tools)?p.tools:[]).slice(0,6).map(x=>str(x,60)),deliverables:(Array.isArray(p.deliverables)?p.deliverables:[]).slice(0,20).map(x=>str(x,500)),estimated:str(p.estimated,100)}));[...D.projects,...clean.customProjects].forEach(p=>{const s=raw.projects?.[p.id];if(s)clean.projects[p.id]={status:['Not started','Building','Ready for review','Complete'].includes(s.status)?s.status:'Not started',url:url(s.url),next:str(s.next),checks:Object.fromEntries(p.deliverables.map((d,i)=>[i,s.checks?.[i]===true]))}});
for(const [key,fields] of Object.entries({logs:['title','area','notes','next'],applications:['title','organisation','location','status','cv','next','notes'],leads:['title','organisation','location','reference','role','fee','eligibility','notes','next'],certificates:['title','provider','type','notes']})){if(!Array.isArray(raw[key]))continue;if(raw[key].length>10000)throw Error('This backup contains too many records.');const used=new Set();clean[key]=raw[key].filter(x=>x&&typeof x==='object').map(x=>{const r={id:validId(x.id),created:str(x.created)||new Date().toISOString()};if(used.has(r.id))r.id=id();used.add(r.id);fields.forEach(k=>r[k]=str(x[k]));['date','applied','followup','deadline','checked'].forEach(k=>r[k]=date(x[k]));r.url=url(x.url);if(key==='logs'){r.minutes=Math.min(1440,Math.max(0,+x.minutes||0));if(!r.date)r.date=today()}if(key==='applications'){r.status=appStages.includes(r.status)?r.status:'Saved';r.leadId=validId(x.leadId);r.history=Array.isArray(x.history)?x.history.slice(-100).filter(h=>h&&appStages.includes(h.status)).map(h=>({date:date(h.date)||today(),status:h.status})):[]}if(key==='leads'){checkFields.forEach(([k])=>r[k]=x[k]===true);if(!['0','Unknown','Fee required'].includes(r.fee))r.fee='Unknown';if(!['Eligible','Not eligible','Need clarification'].includes(r.eligibility))r.eligibility='Need clarification'}return r})}return clean}
async function restoreBackup(file){if(!file)return;if(file.size>5*1024*1024){toast('Choose a JSON backup smaller than 5 MB.');return}try{const clean=validateBackup(JSON.parse(await file.text()));if(!confirm(`Restore ${clean.logs.length} progress entries, ${clean.applications.length} applications and ${clean.leads.length} opportunities? This replaces the current workspace in this browser.`))return;state=clean;if(persist()){$('#modal').close();render();toast('Backup restored successfully')}}catch(e){toast(e.message==='This is not an Analyst Path version 1 backup.'?e.message:'Could not restore this backup. Check that it is a valid Analyst Path JSON file.')}}
document.addEventListener('submit',e=>{if(e.target.id==='record-form'){e.preventDefault();saveRecord(e.target)}});
document.addEventListener('click',async e=>{const learningLink=e.target.closest('[data-learning]');if(learningLink){learnTab=learningLink.dataset.learning;if(route==='learning')render()}const sourceLink=e.target.closest('[data-source-link]');if(sourceLink){focusDataSource(sourceLink.dataset.sourceLink);if(route==='datasets')render()}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,k=b.dataset.id;
const handlers={'data-reset':resetDataSourceFilters,'data-beginner':beginnerDataSources,'data-csv':exportDataSources,'data-project':()=>openDataProject(k),'data-focus':()=>{focusDataSource(k);render();$('#data-source-search').focus()},menu:()=>$('#sidebar').classList.toggle('open'),close:()=>$('#modal').close(),log:()=>openLog(k),project:()=>openProject(k),lead:()=>openLead(k),application:()=>openApplication(k),certificate:()=>openCertificate(k),profile:openProfile,template:()=>openTemplate(k),backup:openBackup,'delete-record':deleteRecord,'project-readme':()=>{if(saveRecord($('#record-form')))openTemplate('readme')},'project-brief':()=>openProjectBrief(k),'edit-project-brief':()=>{if(saveRecord($('#record-form')))openProjectBrief(k)},'learn-tab':()=>{learnTab=k;render()},'resource-filter':()=>{resourceFilter=k;render()},'app-view':()=>{appView=k;render()},continue:()=>{learnTab=D.learning.find(t=>doneFor(t)<6)?.id||'excel';go('learning')},target:()=>{state.profile.target=k;persist();render();toast('Focus role updated')},'from-lead':()=>{const l=state.leads.find(l=>l.id===k);if(l)openApplication(null,l)},csv:csvExport,export:()=>{download('analyst-path-backup-'+today()+'.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Full backup downloaded')},import:()=>$('#import-file').click(),'download-template':()=>{const t=D.templates.find(t=>t.id===modalContext.id);download(t.id+'.txt',t.body,'text/plain');toast('Template downloaded')},'copy-template':async()=>{const t=D.templates.find(t=>t.id===modalContext.id);try{await navigator.clipboard.writeText(t.body);toast('Template copied. Replace the brackets with your facts.')}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents($('.template-body'));selection.removeAllRanges();selection.addRange(range);toast('Template selected. Use your browser’s Copy command.')}}};if(handlers[a])await handlers[a]()});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.dataFilter){dataSourceFilters[el.dataset.dataFilter]=el.value;renderDataSourceResults()}if(el.dataset.task){state.tasks[el.dataset.task]=el.checked;persist();render();toast(el.checked?'Learning step recorded':'Learning step reopened')}if(el.dataset.week){state.week[weekStart()+el.dataset.week]=el.checked;persist();render()}if(el.dataset.confidence){state.skills[el.dataset.confidence]=el.value;persist();toast('Self assessment saved')}if(el.id==='opportunity-filter'){oppFilter=el.value;render()}if(el.id==='application-filter'){appFilter=el.value;render()}if(el.dataset.applicationStatus){const a=state.applications.find(a=>a.id===el.dataset.applicationStatus);if(a){if(['Applied','Assessment','Interview','Offer'].includes(el.value)&&!a.applied){openApplication(a.id);$('#record-form').elements.status.value=el.value;toast('Add the date you applied to complete this change.');render();return}a.status=el.value;a.history=[...(a.history||[]),{date:today(),status:el.value}];persist();render();toast('Application stage updated')}}if(el.id==='import-file')restoreBackup(el.files[0])});
document.addEventListener('input',e=>{if(e.target.id==='data-source-search'){dataSourceFilters.query=e.target.value;renderDataSourceResults()}});
$('#global-search').addEventListener('input',e=>{query=e.target.value;route='search';if(location.hash!=='#search')history.replaceState(null,'','#search');render()});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape')$('#sidebar').classList.remove('open')});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'dashboard';render();window.scrollTo({top:0});$('#sidebar').classList.remove('open')});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
route=location.hash.slice(1)||'dashboard';render();
